#include "storage/qrx_storage_repair_runtime.h"
#include "resource/qrx_storage_repair.h"
#include "storage/qrx_drive_prepare.h"
#include "storage/qrx_postor.h"
#include <openssl/crypto.h>
#include <openssl/evp.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct{QrxDB*db;uint64_t h;QrxStorageRepairStartCandidate*out;size_t cap,n;} StartCtx;
static int start_cb(const char*k,const char*v,uint32_t vl,void*x){(void)v;(void)vl;StartCtx*c=x;if(c->n>=c->cap)return 1;const char*p="storage/assignment/";size_t pn=strlen(p);if(strncmp(k,p,pn))return 0;const char*s=k+pn,*sl=strrchr(s,'/');if(!sl||sl==s)return 0;size_t cn=(size_t)(sl-s);if(cn>=129)return 0;char cid[129];memcpy(cid,s,cn);cid[cn]=0;char*e=NULL;unsigned long sh=strtoul(sl+1,&e,10);if(!e||*e||sh>UINT32_MAX)return 0;QrxStorageAssignmentRecord a;if(qrx_storage_assignment_get(c->db,cid,(uint32_t)sh,&a)||a.state!=QRX_ASSIGN_ACTIVE||!a.accepted_height)return 0;uint64_t base=a.last_proof_height?a.last_proof_height:a.accepted_height;if(UINT64_MAX-base<QRX_STORAGE_PROOF_WINDOW_BLOCKS)return 0;uint64_t due=base+QRX_STORAGE_PROOF_WINDOW_BLOCKS;if(c->h<=due)return 0;QrxStorageRepairStartCandidate*o=&c->out[c->n++];memset(o,0,sizeof(*o));snprintf(o->contract_id,sizeof(o->contract_id),"%s",cid);o->shard_index=(uint32_t)sh;o->assignment=a;o->due_height=due;return 0;}
int qrx_storage_repair_collect_starts(QrxDB*db,uint64_t h,QrxStorageRepairStartCandidate*out,size_t cap,size_t*count){if(!db||!out||!cap||!count)return-1;StartCtx c={db,h,out,cap,0};int rc=qrxdb_scan_prefix(db,"storage/assignment/",start_cb,&c);*count=c.n;return rc<0?-1:0;}

typedef struct{QrxDB*db;const char*provider;uint64_t h;QrxStorageFs*fs;QrxStorageReplacementWork*out;size_t cap,n;} RepCtx;
static int unhex64(const char*s,uint8_t*out){if(!s||strlen(s)!=128)return-1;for(int i=0;i<64;i++){char q[3]={s[i*2],s[i*2+1],0};char*e=NULL;unsigned long v=strtoul(q,&e,16);if(!e||*e)return-1;out[i]=(uint8_t)v;}return 0;}
static int rep_cb(const char*k,const char*v,uint32_t vl,void*x){(void)v;(void)vl;RepCtx*c=x;if(c->n>=c->cap)return 1;const char*p="storage/repair/";size_t pn=strlen(p);if(strncmp(k,p,pn))return 0;const char*s=k+pn,*sl=strrchr(s,'/');if(!sl||sl==s)return 0;size_t cn=(size_t)(sl-s);if(cn>=129)return 0;char cid[129];memcpy(cid,s,cn);cid[cn]=0;char*e=NULL;unsigned long sh=strtoul(sl+1,&e,10);if(!e||*e||sh>UINT32_MAX)return 0;QrxStorageRepairRecord r;if(qrx_storage_repair_get(c->db,cid,(uint32_t)sh,&r)||strcmp(r.replacement_provider_id,c->provider)||(r.state!=QRX_ASSIGN_REPAIRING&&r.state!=QRX_ASSIGN_ACTIVE))return 0;QrxStorageReplacementWork*w=&c->out[c->n++];memset(w,0,sizeof(*w));snprintf(w->contract_id,sizeof(w->contract_id),"%s",cid);w->shard_index=(uint32_t)sh;w->repair=r;w->needs_reconstruction=!qrx_storage_fs_has(c->fs,r.object_id);w->needs_accept=(r.state==QRX_ASSIGN_REPAIRING&&!w->needs_reconstruction);if(r.state==QRX_ASSIGN_ACTIVE&&r.accepted_height&&UINT64_MAX-r.accepted_height>=QRX_STORAGE_PROOF_WINDOW_BLOCKS){w->proof_height=r.accepted_height+QRX_STORAGE_PROOF_WINDOW_BLOCKS;w->proof_epoch=1;w->proof_due=c->h>=w->proof_height;if(w->proof_due){char bh[160];if(!qrxdb_chain_get_block_hash_by_height(c->db,w->proof_height,bh,sizeof(bh))&&strlen(bh)==128){uint8_t b[64];if(!unhex64(bh,b)){QrxPoStorChallenge pc;if(!qrx_postor_derive_challenge(cid,r.replacement_provider_id,(uint32_t)sh,1,r.leaf_count,b,&pc))w->leaf_index=pc.leaf_index;}}}}
return 0;}
int qrx_storage_repair_collect_replacement(QrxDB*db,const char*provider,uint64_t h,QrxStorageFs*fs,QrxStorageReplacementWork*out,size_t cap,size_t*count){if(!db||!provider||!*provider||!fs||!out||!cap||!count)return-1;RepCtx c={db,provider,h,fs,out,cap,0};int rc=qrxdb_scan_prefix(db,"storage/repair/",rep_cb,&c);*count=c.n;return rc<0?-1:0;}
int qrx_storage_repair_start_payload(const QrxStorageRepairStartCandidate*c,char**out){if(!c||!out)return-1;*out=malloc(320);if(!*out)return-1;snprintf(*out,320,"contract_id=%s;shard_index=%u",c->contract_id,c->shard_index);return 0;}
int qrx_storage_repair_accept_payload(const QrxStorageReplacementWork*w,char**out){if(!w||!out)return-1;*out=malloc(320);if(!*out)return-1;snprintf(*out,320,"contract_id=%s;shard_index=%u",w->contract_id,w->shard_index);return 0;}
static int read_leaf(QrxStorageFs*fs,const char*oid,uint64_t bytes,uint64_t idx,unsigned char**out,size_t*len){uint64_t off=idx*(uint64_t)QRX_DRIVE_POSTOR_LEAF_BYTES;if(off>=bytes)return-1;uint64_t rem=bytes-off;size_t n=(size_t)(rem>QRX_DRIVE_POSTOR_LEAF_BYTES?QRX_DRIVE_POSTOR_LEAF_BYTES:rem);return qrx_storage_fs_read_range(fs,oid,off,n,out,len)||*len!=n?-1:0;}
static size_t p2(uint64_t n){size_t p=1;if(!n||n>SIZE_MAX)return 0;while(p<(size_t)n){if(p>SIZE_MAX/2)return 0;p<<=1;}return p;}
static int subtree(QrxStorageFs*fs,const QrxStorageRepairRecord*r,size_t start,size_t width,uint8_t out[64]){if(width==1){uint64_t idx=start<(size_t)r->leaf_count?(uint64_t)start:r->leaf_count-1;unsigned char*b=NULL;size_t n=0;if(read_leaf(fs,r->object_id,r->physical_bytes,idx,&b,&n))return-1;int rc=qrx_merkle_leaf_hash(idx,b,n,out);OPENSSL_cleanse(b,n);free(b);return rc;}uint8_t l[64],rr[64],pair[128];if(subtree(fs,r,start,width/2,l)||subtree(fs,r,start+width/2,width/2,rr))return-1;memcpy(pair,l,64);memcpy(pair+64,rr,64);static const char d[]="QRX-MERKLE-NODE-V1";EVP_MD_CTX*c=EVP_MD_CTX_new();unsigned int n=0;int rc=!c||EVP_DigestInit_ex(c,EVP_sha3_512(),NULL)!=1||EVP_DigestUpdate(c,d,sizeof(d)-1)!=1||EVP_DigestUpdate(c,pair,sizeof(pair))!=1||EVP_DigestFinal_ex(c,out,&n)!=1||n!=64;EVP_MD_CTX_free(c);return rc?-1:0;}
int qrx_storage_repair_build_complete_proof(QrxDB*db,QrxStorageFs*fs,const QrxStorageReplacementWork*w,unsigned char**leaf,size_t*leafn,QrxMerkleProof*proof){if(!db||!fs||!w||!leaf||!leafn||!proof||!w->proof_due||w->repair.state!=QRX_ASSIGN_ACTIVE||w->leaf_index>=w->repair.leaf_count)return-1;char bh[160];if(qrxdb_chain_get_block_hash_by_height(db,w->proof_height,bh,sizeof(bh))||strlen(bh)!=128)return-1;unsigned char*b=NULL;size_t n=0;if(read_leaf(fs,w->repair.object_id,w->repair.physical_bytes,w->leaf_index,&b,&n))return-1;size_t width=p2(w->repair.leaf_count);if(!width){free(b);return-1;}memset(proof,0,sizeof(*proof));proof->leaf_index=w->leaf_index;proof->leaf_count=w->repair.leaf_count;size_t idx=(size_t)w->leaf_index,block=1;while(block<width){if(proof->depth>=QRX_MERKLE_MAX_DEPTH){free(b);return-1;}size_t group=idx/block,start=(group^1u)*block;if(subtree(fs,&w->repair,start,block,proof->siblings[proof->depth])){free(b);return-1;}proof->depth++;block<<=1;}uint8_t lh[64];if(qrx_merkle_leaf_hash(w->leaf_index,b,n,lh)||qrx_merkle_verify_proof(lh,proof,w->repair.merkle_root)){OPENSSL_cleanse(b,n);free(b);return-1;}*leaf=b;*leafn=n;return 0;}
static void hx(const unsigned char*in,size_t n,char*out){static const char*x="0123456789abcdef";for(size_t i=0;i<n;i++){out[i*2]=x[in[i]>>4];out[i*2+1]=x[in[i]&15];}out[n*2]=0;}
int qrx_storage_repair_complete_payload(const QrxStorageReplacementWork*w,const unsigned char*leaf,size_t leafn,const QrxMerkleProof*p,char**out){if(!w||!leaf||!leafn||!p||!out||!w->proof_due||p->leaf_index!=w->leaf_index)return-1;size_t lh=leafn*2,sh=(size_t)p->depth*128,cap=lh+sh+512;char*l=malloc(lh+1),*s=malloc(sh+1),*z=malloc(cap);if(!l||!s||!z){free(l);free(s);free(z);return-1;}hx(leaf,leafn,l);for(uint32_t i=0;i<p->depth;i++)hx(p->siblings[i],64,s+(size_t)i*128);s[sh]=0;snprintf(z,cap,"contract_id=%s;shard_index=%u;epoch=1;challenge_height=%llu;revealed_leaf_hex=%s;siblings_hex=%s",w->contract_id,w->shard_index,(unsigned long long)w->proof_height,l,sh?s:"-");OPENSSL_cleanse(l,lh);free(l);free(s);*out=z;return 0;}
